<?php $d=$record['fields']; ?><h1><?= e(t('Invoice')) ?> <?= e(EmployeeService::invoiceNumber($record['id'])) ?></h1><section class="card"><h2><?= e($client['fields']['name']) ?></h2><p><?= nl2br(e($client['fields']['address']??'')) ?></p><p><?= e(t('Issued')) ?> <?= e($d['issued']) ?> <?= e(t('· Due')) ?> <?= e($d['due']) ?> · <?= e($d['state']) ?></p><div class="table-wrap"><table><tr><th><?= e(t('Item')) ?></th><th><?= e(t('Quantity')) ?></th><th><?= e(t('Unit price')) ?></th><th><?= e(t('Total')) ?></th></tr><?php foreach(EmployeeService::rows('invoice_lines')as $line):$v=$line['fields'];if($v['invoice']!==$record['id'])continue; ?><tr><td><?= e($v['description']) ?></td><td><?= e($v['quantity']) ?></td><td><?= e(number_format($v['unit_price'],2)) ?></td><td><?= e(number_format($v['quantity']*$v['unit_price'],2)) ?></td></tr><?php endforeach; ?></table></div><p><?= e(t('Total')) ?> <?= e($d['currency']) ?> <?= e(number_format(EmployeeService::invoiceTotal($record['id']),2)) ?> <?= e(t('· Paid')) ?> <?= e(number_format($d['paid'],2)) ?></p><p><?= nl2br(e($d['notes']??'')) ?></p><p><?= e(t('Use Print / Save as PDF to export.')) ?></p></section>
